import{_ as a,c as s,x as e,a as o,t as c,Q as t,o as n}from"./chunks/framework.5f28ab71.js";const F=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"compiler/构建compile/4-转化策略和注意事项.md","lastUpdated":1724243587000}'),l={name:"compiler/构建compile/4-转化策略和注意事项.md"},d=t(`<h2 id="ast-到-javascript-ast-的转化策略和注意事项" tabindex="-1">AST 到 JavaScript AST 的转化策略和注意事项 <a class="header-anchor" href="#ast-到-javascript-ast-的转化策略和注意事项" aria-label="Permalink to &quot;AST 到 JavaScript AST 的转化策略和注意事项&quot;">​</a></h2><p>在生成了 <code>AST</code> 之后，我们知道接下来就需要把 <code>AST</code> 转化为 <code>JavaScript AST</code> 了，但是在转化的过程中，有一些对应的策略和注意事项。</p><h3 id="转化策略" tabindex="-1">转化策略 <a class="header-anchor" href="#转化策略" aria-label="Permalink to &quot;转化策略&quot;">​</a></h3><p>我们知道从 <code>AST</code> 转化为 <code>JavaScript AST</code> 本质上是一个对象结构的变化，变化的本质是为了后面更方便的解析对象，生成 <code>render</code> 函数。</p><p>在转化的过程中，我们需要遵循如下策略：</p><ol><li>深度优先</li><li>转化函数分离</li><li>上下文对象</li></ol><h4 id="深度优先" tabindex="-1">深度优先 <a class="header-anchor" href="#深度优先" aria-label="Permalink to &quot;深度优先&quot;">​</a></h4><p>我们知道 <code>AST</code> 而言，它是包含层级的，比如：</p><ol><li>最外层是 <code>ROOT</code></li><li><code>children</code> 是根节点</li><li>…</li></ol><p>这样的结构下，就会存在一个自上而下的层级，那么针对这样的一个层级而言，我们需要遵循 <strong>深度优先，自下而上</strong> 的一个转化方案。</p><p>因为父节点的状态往往需要根据子节点的情况才能够进行确定，比如：</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#89DDFF;">&lt;</span><span style="color:#F07178;">div</span><span style="color:#89DDFF;">&gt;</span><span style="color:#A6ACCD;">hello world</span><span style="color:#89DDFF;">&lt;/</span><span style="color:#F07178;">div</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"><span style="color:#89DDFF;">&lt;</span><span style="color:#F07178;">div</span><span style="color:#89DDFF;">&gt;</span><span style="color:#A6ACCD;">hello {{ msg }}</span><span style="color:#89DDFF;">&lt;/</span><span style="color:#F07178;">div</span><span style="color:#89DDFF;">&gt;</span></span>
<span class="line"></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h4 id="转化函数分离" tabindex="-1">转化函数分离 <a class="header-anchor" href="#转化函数分离" aria-label="Permalink to &quot;转化函数分离&quot;">​</a></h4><p>在处理 <code>AST</code> 的时候，我们知道，针对于不同的 <code>token</code>，那么会使用不同的 <code>parseXXX</code> 方法进行处理，那么同样的，在 <code>transform</code> 的过程中，我们也会通过不同的 <code>transformXXX</code> 方法进行转化。</p><p>但是为了防止 <code>transform</code> 模块过于臃肿，所以我们会通过 <code>options</code>的方式对 <code>transformXXX</code> 方法进行注入（类似于 <code>render 的 option</code>）。</p><p>所有注入的方法，会生成一个 <code>nodeTransforms</code> 数组，通过 <code>options</code> 传入。</p><h4 id="上下文对象" tabindex="-1">上下文对象 <a class="header-anchor" href="#上下文对象" aria-label="Permalink to &quot;上下文对象&quot;">​</a></h4><p>上下文对象即 <code>context</code>，对于上下文对象而言我们其实并不陌生。比如在 <code>parse</code> 时、 <code>setup 函数中</code>、 <code>vuex 的 action</code> 上，都出现过 <code>context</code> 对象。</p><p>对于 <code>context</code> 而言，我们可以把它理解为一个 全局变量 或者 单例的全局变量，它是一个多模块都可以访问的唯一对象。</p><p>在 <code>transform</code> 的策略中，因为存在 <strong>转化函数分离</strong> 这样的一个特性，所以我们我们必须要构建出这样的一个 <code>context</code> 对象，用来保存 当前的 <code>node</code> 节点 等数据</p><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><p>说完了转化策略之后，我们来看下注意事项。</p>`,22),r=e("code",null,"transform",-1),p=e("code",null,"vue",-1),i=e("p",null,"但是对于我们当前而言，我们不考虑这些复杂的情况，仅查看最简单的静态数据渲染，以此来简化整体逻辑。",-1);function h(_,m,u,D,S,b){return n(),s("div",null,[d,e("p",null,[o("对于 "),r,o(" 转化方法而言，"),p,o(" 本身的实现非常复杂，比如：指令、"),e("code",null,c(),1),o(" … 都会在这里处理。")]),i])}const T=a(l,[["render",h]]);export{F as __pageData,T as default};
